WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_prices) AS element FROM price_tiers) SELECT CASE WHEN element >= 81 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, SIZE(COLLECT_SET(currency)) AS num_currencies, MIN(element) AS min_element, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN plan = 'pro' THEN 1 END), 0), 2) AS element_per_pro, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, ROUND(AVG(element), 2) AS avg_element, APPROX_PERCENTILE(element, 0.95) AS element_p95, GROUPING(CASE WHEN element >= 81 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM lines GROUP BY CUBE (CASE WHEN element >= 81 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY num_currencies NULLS FIRST;
